class CliTestCase(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.dir = tmp.name
        self.path = self.write("house.txt", LEDGER)

    def write(self, name, text, newline=None):
        path = os.path.join(self.dir, name)
        with open(path, "w", encoding="utf-8", newline=newline) as fh:
            fh.write(text)
        return path

    def read_bytes(self, path):
        with open(path, "rb") as fh:
            return fh.read()


class BalanceTests(CliTestCase):
    def test_balance(self):
        self.assertEqual(run(["balance", self.path]), (0, "1557.50\n", ""))

    def test_balance_empty(self):
        empty = self.write("e.txt", "")
        self.assertEqual(run(["balance", empty]), (0, "0.00\n", ""))

    def test_balance_negative_zero_prints_zero(self):
        p = self.write("z.txt", "2024-01-01 a -0.00\n")
        self.assertEqual(run(["balance", p])[1], "0.00\n")

    def test_balance_json(self):
        self.assertEqual(
            run(["balance", self.path, "--json"]), (0, '{"balance": "1557.50"}\n', "")
        )


